using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AquarianOrbsOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/AquarianOrbs Omen Data")]
public class AquarianOrbsOmenData : OnStartOfBattleOmenData
{
	[Header("Aquarian Orbs")]
	[SerializeField]
	private VoidEvent OnInitializeOrionOrbs;

	[SerializeField]
	private StarAbility[] starAbilities;

	public StarAbility[] StarAbilities => starAbilities;

	public override void ActivateOmen(GameObject target = null)
	{
		OnInitializeOrionOrbs.Raise();
	}
}
